files.content:
:root {
  --bg: #f4f1de;
  --card-bg: #ffffff;
  --text: #3d405b;
  --accent: #e07a5f;
  --accent-hover: #c96a50;
  --accent-active: #b35a42;
  --available: #81b29a;
  --checked-out: #e07a5f;
  --border: #e0e0e0;
  --focus: #3d5a80;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  padding: 28px 24px;
  width: 100%;
  max-width: 560px;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0 0 20px;
  color: #6b6e85;
  font-size: 0.95rem;
}

.stats {
  margin-bottom: 16px;
  font-weight: 600;
  font-size: 1.1rem;
  color: var(--accent);
}

.filter-row {
  margin-bottom: 20px;
}

.filter-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 0.95rem;
  user-select: none;
}

.filter-label input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
  cursor: pointer;
}

.book-list {
  list-style: none;
  margin: 0 0 16px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.book-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fafafa;
  flex-wrap: wrap;
}

.book-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1 1 160px;
}

.book-title {
  font-weight: 600;
  font-size: 1rem;
  word-break: break-word;
}

.book-author {
  font-size: 0.85rem;
  color: #6b6e85;
}

.book-status {
  font-size: 0.8rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
  white-space: nowrap;
}

.book-status.available {
  background: #d8f0e5;
  color: #2d6a4f;
}

.book-status.checked-out {
  background: #fde2d9;
  color: #9c3b1f;
}

.btn {
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 8px 16px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn-checkout {
  background: var(--accent);
  color: #fff;
}

.btn-checkout:hover {
  background: var(--accent-hover);
}

.btn-checkout:active {
  background: var(--accent-active);
  transform: scale(0.97);
}

.btn-return {
  background: var(--available);
  color: #fff;
}

.btn-return:hover {
  background: #6a9e86;
}

.btn-return:active {
  background: #558a72;
  transform: scale(0.97);
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: #9a9cb0;
  text-align: center;
}

@media (max-width: 400px) {
  .card {
    padding: 20px 16px;
  }
  h1 {
    font-size: 1.35rem;
  }
  .book-item {
    padding: 10px 12px;
  }
  .btn {
    font-size: 0.85rem;
    padding: 7px 12px;
  }
}

const books = [
  { id: 1, title: 'The Pixel Frontier', author: 'Ada Lovelace', available: true },
  { id: 2, title: 'CSS: A Love Story', author: 'Grace Hopper', available: false },
  { id: 3, title: 'JavaScript: The Good Parts', author: 'Douglas Crockford', available: true },
  { id: 4, title: 'Designing with Grid', author: 'Alan Turing', available: true },
  { id: 5, title: 'The Art of Refactoring', author: 'Martin Fowler', available: false },
  { id: 6, title: 'Algorithms in Bloom', author: 'Barbara Liskov', available: true }
];

const bookListEl = document.getElementById('book-list');
const countEl = document.getElementById('checked-out-count');
const filterEl = document.getElementById('available-filter');

function getCheckedOutCount() {
  return books.filter(b => !b.available).length;
}

function updateCount() {
  const count = getCheckedOutCount();
  countEl.textContent = `${count} checked out`;
}

function render() {
  const showAvailableOnly = filterEl.checked;
  bookListEl.innerHTML = '';

  books.forEach(book => {
    if (showAvailableOnly && !book.available) return;

    const li = document.createElement('li');
    li.className = 'book-item';

    const info = document.createElement('div');
    info.className = 'book-info';

    const title = document.createElement('span');
    title.className = 'book-title';
    title.textContent = book.title;

    const author = document.createElement('span');
    author.className = 'book-author';
    author.textContent = book.author;

    info.appendChild(title);
    info.appendChild(author);

    const status = document.createElement('span');
    status.className = `book-status ${book.available ? 'available' : 'checked-out'}`;
    status.textContent = book.available ? 'Available' : 'Checked out';

    const btn = document.createElement('button');
    btn.className = `btn ${book.available ? 'btn-checkout' : 'btn-return'}`;
    btn.textContent = book.available ? 'Check out' : 'Return';
    btn.setAttribute('aria-label', `${book.available ? 'Check out' : 'Return'} ${book.title}`);
    btn.addEventListener('click', () => {
      book.available = !book.available;
      updateCount();
      render();
    });

    li.appendChild(info);
    li.appendChild(status);
    li.appendChild(btn);
    bookListEl.appendChild(li);
  });

  updateCount();
}

filterEl.addEventListener('change', render);

render();
